/**
 * @summary Admin - list all comments
 */
export const getAdminListCommentsUrl = (params?: AdminListCommentsParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/admin/comments?${stringifiedParams}`
    : `/api/admin/comments`;
};

export const adminListComments = async (
  params?: AdminListCommentsParams,
  options?: RequestInit,
): Promise<PaginatedComments> => {
  return customFetch<PaginatedComments>(getAdminListCommentsUrl(params), {
    ...options,
    method: "GET",
  });
};

